CREATE OR REPLACE FUNCTION public.bootstrap_system_owner(p_pharmacy_name text, p_pharmacy_code text)
 RETURNS TABLE(pharmacy_id uuid, pharmacy_code text, pharmacy_name text, system_role text, member_role text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_user uuid := auth.uid();
    v_existing_owner uuid;
    v_pharmacy uuid;
    v_code text;
begin
    if v_user is null then
        raise exception 'Authentication required';
    end if;

    -- Prevent two browsers from winning first-owner setup at the same time.
    perform pg_advisory_xact_lock(hashtext('medryvo_bootstrap_system_owner'));

    select so.user_id
      into v_existing_owner
      from public.system_owners so
      order by so.created_at asc
      limit 1;

    if v_existing_owner is not null and v_existing_owner <> v_user then
        raise exception 'System owner is already configured';
    end if;

    if nullif(trim(p_pharmacy_name),'') is null then
        raise exception 'Pharmacy name is required';
    end if;

    v_code := upper(regexp_replace(coalesce(p_pharmacy_code,''), '[^A-Za-z0-9_-]+', '', 'g'));
    if length(v_code) < 3 then
        raise exception 'Pharmacy code must be at least 3 characters';
    end if;

    -- Owner record can safely be retried by the SAME authenticated user.
    insert into public.system_owners(user_id)
    values (v_user)
    on conflict (user_id) do nothing;

    -- If this same Owner already has an admin pharmacy membership, return it.
    select p.id
      into v_pharmacy
      from public.pharmacy_members pm
      join public.pharmacies p on p.id = pm.pharmacy_id
     where pm.user_id = v_user
       and pm.role = 'admin'
     order by pm.created_at asc
     limit 1;

    if v_pharmacy is null then
        insert into public.pharmacies(
            code, name, active, status, approved_at, approved_by
        )
        values (
            v_code, trim(p_pharmacy_name), true, 'active', now(), v_user
        )
        on conflict (code) do update
        set name = excluded.name,
            active = true,
            status = 'active',
            approved_at = coalesce(public.pharmacies.approved_at, now()),
            approved_by = coalesce(public.pharmacies.approved_by, v_user),
            updated_at = now()
        returning id into v_pharmacy;

        insert into public.pharmacy_members(pharmacy_id, user_id, role, active)
        values (v_pharmacy, v_user, 'admin', true)
        on conflict (pharmacy_id, user_id) do update
        set role = 'admin', active = true;
    end if;

    return query
    select p.id,
           p.code,
           p.name,
           'owner'::text,
           'admin'::text
      from public.pharmacies p
     where p.id = v_pharmacy;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.cancel_pharmflow_expiry_capture_v1(p_pharmacy_id uuid, p_operation_id uuid, p_reason text DEFAULT 'USER_CANCELLED'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE o pharmflow_expiry_private.operations%rowtype;
BEGIN
 PERFORM pharmflow_expiry_private.valid_auth_session();
 IF auth.uid() IS NULL OR public.is_pharmacy_member(p_pharmacy_id) IS NOT TRUE THEN RAISE EXCEPTION 'Pharmacy access required'; END IF;
 IF p_operation_id IS NULL OR p_reason IS NULL OR p_reason NOT IN ('USER_CANCELLED','ABANDON_CONFIRMED') THEN RAISE EXCEPTION 'Explicit cancellation required'; END IF;
 INSERT INTO pharmflow_expiry_private.operations(pharmacy_id,operation_id,created_by) VALUES(p_pharmacy_id,p_operation_id,auth.uid()) ON CONFLICT DO NOTHING;
 SELECT * INTO o FROM pharmflow_expiry_private.operations WHERE pharmacy_id=p_pharmacy_id AND operation_id=p_operation_id FOR UPDATE;
 IF o.created_by<>auth.uid() THEN RAISE EXCEPTION 'Operation owner conflict'; END IF;
 IF o.status='CANCELLED' THEN RETURN jsonb_build_object('operation_id',p_operation_id,'status','CANCELLED'); END IF;
 IF o.status<>'RESERVED' OR o.payload IS NOT NULL OR o.result IS NOT NULL
 OR EXISTS(SELECT 1 FROM pharmflow_expiry_private.review_details d WHERE d.pharmacy_id=p_pharmacy_id AND d.operation_id=p_operation_id)
 OR EXISTS(SELECT 1 FROM public.pharmflow_needs_review_v2 r WHERE r.pharmacy_id=p_pharmacy_id AND r.workflow='EXPIRY' AND r.operation_id=p_operation_id::text)
 THEN RAISE EXCEPTION 'Committed or in-flight capture cannot be cancelled'; END IF;
 UPDATE pharmflow_expiry_private.operations SET status='CANCELLED',cancelled_by=auth.uid(),cancelled_at=now(),cancellation_reason=p_reason
 WHERE pharmacy_id=p_pharmacy_id AND operation_id=p_operation_id;
 RETURN jsonb_build_object('operation_id',p_operation_id,'status','CANCELLED');
END $function$
;

