CREATE OR REPLACE FUNCTION public.commit_global_master_gtin_import(p_import_id uuid)
 RETURNS TABLE(version text, item_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_source text;
    v_version text:=gen_random_uuid()::text;
    v_count integer;
begin
    if auth.uid() is null or not public.is_system_owner() then
        raise exception 'System Owner permission required';
    end if;

    select source_file into v_source
    from public.pharmflow_global_gtin_imports_v1
    where id=p_import_id and created_by=auth.uid();
    if not found then raise exception 'Global GTIN import not found'; end if;

    -- Conflicts inside the new file: one GTIN claims more than one Item Code.
    insert into public.pharmflow_global_gtin_conflicts_v1(
        import_id,gtin,existing_item_code,incoming_item_code,incoming_item_name,reason,created_by
    )
    select p_import_id,r.gtin,null,r.item_code,max(r.item_name),'SAME FILE: GTIN linked to multiple Item Codes',auth.uid()
    from public.pharmflow_global_gtin_import_rows_v1 r
    where r.import_id=p_import_id
      and r.gtin in (
        select x.gtin from public.pharmflow_global_gtin_import_rows_v1 x
        where x.import_id=p_import_id group by x.gtin having count(distinct x.item_code)>1
      )
    group by r.gtin,r.item_code;

    -- Conflicts against the current trusted Global Master.
    insert into public.pharmflow_global_gtin_conflicts_v1(
        import_id,gtin,existing_item_code,incoming_item_code,incoming_item_name,reason,created_by
    )
    select distinct p_import_id,r.gtin,g.item_code,r.item_code,r.item_name,
           'GLOBAL MASTER: GTIN already linked to a different Item Code',auth.uid()
    from public.pharmflow_global_gtin_import_rows_v1 r
    join public.pharmflow_global_gtin_v1 g on g.gtin=r.gtin and g.item_code<>r.item_code
    where r.import_id=p_import_id;

    -- ADD / UPDATE only. Never delete old GTINs merely because a monthly file omitted them.
    insert into public.pharmflow_global_gtin_v1(item_code,gtin,item_name,category)
    select r.item_code,r.gtin,max(r.item_name),max(r.category)
    from public.pharmflow_global_gtin_import_rows_v1 r
    where r.import_id=p_import_id
      and r.gtin not in (
        select x.gtin from public.pharmflow_global_gtin_import_rows_v1 x
        where x.import_id=p_import_id group by x.gtin having count(distinct x.item_code)>1
      )
      and not exists(
        select 1 from public.pharmflow_global_gtin_v1 g
        where g.gtin=r.gtin and g.item_code<>r.item_code
      )
    group by r.item_code,r.gtin
    on conflict(item_code,gtin) do update set
        item_name=case when excluded.item_name<>'' then excluded.item_name else public.pharmflow_global_gtin_v1.item_name end,
        category=case when excluded.category<>'' then excluded.category else public.pharmflow_global_gtin_v1.category end;

    select count(*) into v_count from public.pharmflow_global_gtin_v1;
    update public.pharmflow_global_gtin_meta_v1
    set version=v_version,source_file=coalesce(v_source,''),item_count=v_count,
        updated_at=now(),updated_by=auth.uid()
    where singleton=true;

    delete from public.pharmflow_global_gtin_imports_v1 where id=p_import_id;
    return query select v_version,v_count;
end $function$
;

