 on conflict(item_code,gtin) do update set item_name=case when excluded.item_name<>'' then excluded.item_name else public.pharmflow_global_gtin_v1.item_name end,group_name=case when excluded.group_name<>'' then excluded.group_name else public.pharmflow_global_gtin_v1.group_name end,category=case when excluded.category<>'' then excluded.category else public.pharmflow_global_gtin_v1.category end,sub_category=case when excluded.sub_category<>'' then excluded.sub_category else public.pharmflow_global_gtin_v1.sub_category end;
